import sqlite3
import unittest
from users import find_user

class QuerySecurityTests(unittest.TestCase):
    def setUp(self):
        self.db = sqlite3.connect(":memory:")
        self.db.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)")
        self.db.executemany("INSERT INTO users (id,name) VALUES (?,?)", [(1,"alice"),(2,"bob"),(3,"O'Reilly")])
    def tearDown(self):
        self.db.close()
    def test_legitimate_name(self):
        self.assertEqual(find_user(self.db, "alice"), [(1,)])
    def test_unknown_name(self):
        self.assertEqual(find_user(self.db, "nobody"), [])
    def test_quote_in_legitimate_name(self):
        self.assertEqual(find_user(self.db, "O'Reilly"), [(3,)])
    def test_injected_predicate_cannot_select_other_users(self):
        self.assertEqual(find_user(self.db, "' OR 1=1 --"), [])
    def test_injection_cannot_drop_users(self):
        try:
            find_user(self.db, "'; DROP TABLE users; --")
        except sqlite3.Error:
            self.fail("input must be bound as data, not parsed as SQL")
        self.assertEqual(self.db.execute("SELECT COUNT(*) FROM users").fetchone()[0], 3)
